def transform(grid):
    h, w = len(grid), len(grid[0])
    barrier = None
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            barrier = ("up" if r < h / 2 else "down", r)
            break
    if barrier is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                barrier = ("left" if c < w / 2 else "right", c)
                break
    if barrier is None:
        return [row[:] for row in grid]

    direction, line = barrier
    out = [[0] * w for _ in range(h)]
    if direction == "up":
        out[line] = grid[line][:]
    elif direction == "down":
        out[line] = grid[line][:]
    elif direction == "left":
        for r in range(h):
            out[r][line] = grid[r][line]
    else:
        for r in range(h):
            out[r][line] = grid[r][line]

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
