            if direction in ("up", "down") and r == line:
                continue
            if direction in ("left", "right") and c == line:
                continue
            if (r, c) in seen:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        if (direction in ("up", "down") and ny == line) or (direction in ("left", "right") and nx == line):
                            continue
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    if direction == "up":
        objects.sort(key=lambda obj: min(y for y, x in obj[1]))
        dy, dx = -1, 0
    elif direction == "down":
        objects.sort(key=lambda obj: -max(y for y, x in obj[1]))
        dy, dx = 1, 0
    elif direction == "left":
        objects.sort(key=lambda obj: min(x for y, x in obj[1]))
        dy, dx = 0, -1
    else:
        objects.sort(key=lambda obj: -max(x for y, x in obj[1]))
        dy, dx = 0, 1

    for color, cells in objects:
        cells = list(cells)
